head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};

    scwin.button1_onclick = function() {
        spinner1.setIncrement(0.1);
    }
    scwin.button2_onclick = function() {
        var val = spinner1.getIncrement();
        console.log(val);
		window.checkLog = val;
    }


	scwin.checkVal1 = function() {
		return window.checkLog == '0.1';
	}		
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('spinner1___input').value == '100.1';
	}			
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('button1').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('button2').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('spinner1_upButton_image').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");				

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
